import * as THREE from 'three/webgpu';
import { texture as textureNode } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Design palette
  const COLOR_PAPER = 0xe8ecf2;

  // Create background plane (1.6:1 aspect from 512x320)
  const planeGeometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Load and configure texture
  const mapTexture = ctx.textureLoader.load(config.imageUrl);
  mapTexture.colorSpace = THREE.SRGBColorSpace;

  // Create material with TSL
  const mapColorNode = textureNode(mapTexture);
  const planeMaterial = new THREE.MeshBasicNodeMaterial({
    colorNode: mapColorNode
  });

  // Create and position plane
  const plane = new THREE.Mesh(planeGeometry, planeMaterial);
  plane.position.copy(config.scenePosition);
  if (config.sceneRotation) {
    plane.rotation.order = 'YXZ';
    plane.rotation.setFromVector3(config.sceneRotation);
  }
  if (config.sceneScale) {
    plane.scale.copy(config.sceneScale);
  }

  group.add(plane);

  // Render text content via fontAtlas
  if (config.textContent?.length > 0) {
    const textSpec = config.textContent[0];
    const textMesh = ctx.fontAtlas.createTextMesh(textSpec.text, {
      font: 'Lora',
      size: 0.34,
      weight: 400,
      color: COLOR_PAPER
    });

    textMesh.position.set(-0.6, 0, 0.01);
    group.add(textMesh);
  }

  // Cleanup handler
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    planeMaterial.dispose();
    mapTexture.dispose();
    gsap.killTweensOf(group);
  };

  // Event handlers
  group.userData.handlers = {};

  return group;
}
